const documentKeysIn = `-- name: DocumentKeysIn :many
SELECT object_key FROM pharmacy_documents WHERE object_key = ANY($1::text[])
`

func (q *Queries) DocumentKeysIn(ctx context.Context, keys []string) ([]string, error) {
	rows, err := q.db.Query(ctx, documentKeysIn, keys)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var object_key string
		if err := rows.Scan(&object_key); err != nil {
			return nil, err
		}
		items = append(items, object_key)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

