const inbox = `-- name: Inbox :many
SELECT t.alert_id, t.distance_m, t.status AS target_status, t.notified_at,
       a.kind, a.medicine_name, a.quantity, a.note, a.photo_key, a.status AS alert_status, a.search_ends_at,
       a.generic_accepted, t.seen_at, a.number,
       -- Position du client : sert seulement à trouver son quartier, jamais renvoyée à la pharmacie.
       ST_Y(a.location::geometry)::float8 AS lat, ST_X(a.location::geometry)::float8 AS lng
FROM pharmacy_alert_targets t
JOIN pharmacy_alerts a ON a.id = t.alert_id
WHERE t.pharmacy_id = $1
  AND (NOT $2::bool OR (t.status IN ('pending', 'responded') AND a.status IN ('searching', 'answered', 'unlocked')))
ORDER BY t.notified_at DESC
LIMIT $4 OFFSET $3
`

type InboxParams struct {
	PharmacyID uuid.UUID
	OpenOnly   bool
	Off        int32
	Lim        int32
}

type InboxRow struct {
	AlertID         uuid.UUID
	DistanceM       int32
	TargetStatus    string
	NotifiedAt      time.Time
	Kind            string
	MedicineName    string
	Quantity        int32
	Note            string
	PhotoKey        *string
	AlertStatus     string
	SearchEndsAt    time.Time
	GenericAccepted bool
	SeenAt          *time.Time
	Number          int64
	Lat             float64
	Lng             float64
}

// Alertes adressées à la pharmacie (sans aucune donnée du client).
func (q *Queries) Inbox(ctx context.Context, arg InboxParams) ([]InboxRow, error) {
	rows, err := q.db.Query(ctx, inbox,
		arg.PharmacyID,
		arg.OpenOnly,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []InboxRow{}
	for rows.Next() {
		var i InboxRow
		if err := rows.Scan(
			&i.AlertID,
			&i.DistanceM,
			&i.TargetStatus,
			&i.NotifiedAt,
			&i.Kind,
			&i.MedicineName,
			&i.Quantity,
			&i.Note,
			&i.PhotoKey,
			&i.AlertStatus,
			&i.SearchEndsAt,
			&i.GenericAccepted,
			&i.SeenAt,
			&i.Number,
			&i.Lat,
			&i.Lng,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

