const pharmacyEarnings = `-- name: PharmacyEarnings :one
SELECT
  coalesce((SELECT sum(r1.pharmacy_due_xof) FROM pharmacy_reservations r1
            WHERE r1.pharmacy_id = $1 AND r1.status = 'completed' AND r1.fulfillment = 'delivery'), 0)::bigint AS due_xof,
  coalesce((SELECT count(*) FROM pharmacy_reservations r2
            WHERE r2.pharmacy_id = $1 AND r2.status = 'completed' AND r2.fulfillment = 'delivery'), 0)::bigint AS delivered_count,
  coalesce((SELECT count(*) FROM pharmacy_reservations r3
            WHERE r3.pharmacy_id = $1 AND r3.status = 'completed' AND r3.fulfillment = 'pickup'), 0)::bigint AS pickup_count,
  coalesce((SELECT sum(po.amount_xof) FROM pharmacy_payouts po WHERE po.pharmacy_id = $1), 0)::bigint AS paid_out_xof
`

type PharmacyEarningsRow struct {
	DueXof         int64
	DeliveredCount int64
	PickupCount    int64
	PaidOutXof     int64
}

func (q *Queries) PharmacyEarnings(ctx context.Context, pharmacyID uuid.UUID) (PharmacyEarningsRow, error) {
	row := q.db.QueryRow(ctx, pharmacyEarnings, pharmacyID)
	var i PharmacyEarningsRow
	err := row.Scan(
		&i.DueXof,
		&i.DeliveredCount,
		&i.PickupCount,
		&i.PaidOutXof,
	)
	return i, err
}

